import java.util.*;

class Solution {
    public int maxShopTotal(int[][] sales) {
        int best = 0;
        for (int[] row : sales) {
            int sum = 0;                         // fresh total for this shop
            for (int v : row) sum += v;
            best = Math.max(best, sum);          // keep the largest total
        }
        return best;
    }
}

